const CACHE='occci-announcement-carousel-v47';
const ASSETS=['./','./index.html','./app.js','./realtime.js','./realtime-client.js','./reports.js','./staff-invites.js','./finance.js','./cashier-password.js','./notifications.js','./supabase-config.js','./ui.js','./styles.css','./design.css','./design.js','./announcements.js','./occci-logo.png','./icon.svg','./icon-192.png','./icon-512.png','./manifest.json','./fonts/Poppins-Regular.woff','./fonts/Poppins-SemiBold.woff','./fonts/Poppins-Bold.woff'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)));self.skipWaiting()});
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;const isAsset=ASSETS.some(asset=>new URL(asset,self.registration.scope).pathname===url.pathname);if(!isAsset&&event.request.mode!=='navigate')return;event.respondWith(fetch(event.request).catch(()=>caches.match(event.request,{ignoreSearch:true}).then(cached=>cached||(event.request.mode==='navigate'?caches.match('./index.html'):Response.error()))))});
